const stkTrilhaBtn=()=>`<button class="btn sec" onclick="listaDrawer('Registro de atividades do estoque',STK_AUD.map(a=>'<b>'+esc(a.acao)+'</b><small>'+a.h+' · '+esc(a.quem)+'</small>'),'Cada lançamento, estorno, pedido e inventário fica registrado com quem e quando. Nada é apagado.')" ${tipAttr('Atividades','Registro de atividades de cada pessoa no estoque.')}>Atividades</button>`;

/* ---------- Cálculos (os mesmos do sistema de estoque) ---------- */
const stkQ=v=>(Math.round((v||0)*1000)/1000).toLocaleString('pt-BR');
const stkUnids=()=>STK_U?[STK_U]:[10,12,14];
const stkSaldo=(i,u)=>(u?[u]:stkUnids()).reduce((s,x)=>s+(i.s[x]||0),0);
const stkFacU=(u)=>(u?[u]:stkUnids()).reduce((s,x)=>s+STK_FAC[x],0);
const stkCm=(i,u)=>i.cm*stkFacU(u);
const stkMin=(i,u)=>i.min==null?null:Math.ceil(i.min*stkFacU(u));
const stkMax=(i,u)=>i.max==null?null:Math.ceil(i.max*stkFacU(u));
function stkEmPedido(c,u){if((u||STK_U)&&(u||STK_U)!==10)return 0;return STK_PD.filter(p=>p.st==='ABERTO'||p.st==='PARCIAL').reduce((s,p)=>s+p.it.filter(x=>x.c===c).reduce((t,x)=>t+Math.max(0,x.e*STK(c).fator-x.r),0),0)}
function stkSit(i,u){const s=stkSaldo(i,u),mn=stkMin(i,u),mx=stkMax(i,u);if(!i.ativo)return 'INATIVO';if(mn==null&&mx==null)return 'SEM_MINMAX';if(s<=0.00001)return 'ZERADO';if(mn!=null&&s<=mn)return 'REPOR';if(mx!=null&&s>mx)return 'ACIMA';return 'OK'}
const STK_SIT={OK:['OK','ok'],ACIMA:['Acima do máx.','info'],REPOR:['Repor','warn'],ZERADO:['Zerado','err'],SEM_MINMAX:['Sem mín/máx','neutral'],INATIVO:['Inativo','neutral']};
const stkSitTag=k=>`<span class="badge ${STK_SIT[k][1]}">${STK_SIT[k][0]}</span>`;
const stkSugMin=(i,u)=>i.cm>0?Math.ceil(stkCm(i,u)/30*STK_CFG.cobMin):null;
const stkSugMax=(i,u)=>i.cm>0?Math.max(Math.ceil(stkCm(i,u)/30*STK_CFG.cobMax),stkSugMin(i,u)+1):null;
const stkCob=(i,u)=>{const d=stkCm(i,u)/30;return d>0?Math.round(Math.max(stkSaldo(i,u),0)/d):null};
/* Necessidade pela agenda dos próximos 14 dias (kits × atendimentos marcados) ★ */
function stkAgenda(c){return Object.entries(STK_AGF).reduce((s,[p,n])=>s+(STK_KIT[p]||[]).filter(k=>k[0]===c).reduce((t,k)=>t+k[1]*n,0),0)}
function stkAgendaExtra(i){if(STK_U&&STK_U!==10)return 0;return Math.max(0,stkAgenda(i.c)-stkCm(i,10)/30*14)}
/* Sugestão de compra: critério mínimo (só quem chegou ao mínimo) ou máximo (todo item abaixo do máximo); compra até o máximo, em embalagens */
function stkSugestao(i,crit,agenda){const mx=stkMax(i,STK_U),mn=stkMin(i,STK_U);if(!i.ativo||mx==null||mx<=0)return {un:0,emb:0,val:0};const disp=Math.max(stkSaldo(i,STK_U),0)+stkEmPedido(i.c,STK_U);const extra=agenda?stkAgendaExtra(i):0;const alvo=mx+extra;const precisa=crit==='maximo'?disp<alvo-0.00001:(disp<=(mn||0)+0.00001||(agenda&&extra>0&&disp<alvo));if(!precisa)return {un:0,emb:0,val:0};const un=Math.max(0,alvo-disp);const emb=Math.ceil(un/(i.fator||1)-1e-9);return {un,emb,val:Math.round(emb*i.fator*i.custo*100)/100,extra}}
function stkABC(u){const l=STK_IT.filter(i=>i.ativo&&i.cm>0&&i.custo>0).map(i=>({i,v:stkCm(i,u)*i.custo})).sort((a,b)=>b.v-a.v);const tot=l.reduce((s,x)=>s+x.v,0);let ac=0;l.forEach(x=>{ac+=x.v;x.ac=ac/tot*100;x.cl=x.ac-x.v/tot*100<80?'A':x.ac-x.v/tot*100<95?'B':'C';x.pct=x.v/tot*100});return {l,tot}}
const stkCurva=c=>{const x=stkABC(STK_U).l.find(y=>y.i.c===c);return x?x.cl:'—'};
/* Validade */
const stkDias=v=>v?Math.round((new Date(v+'T12:00:00')-STK_HOJE)/864e5):null;
const stkVSit=d=>d===null?'SEM_DATA':d<0?'VENCIDO':d<=30?'ATE30':d<=STK_CFG.alerta?'ALERTA':'OK';
const STK_VS={VENCIDO:['Vencido','err'],ATE30:['Vence em até 30 dias','warn'],ALERTA:['Alerta','acc'],OK:['No prazo','ok'],SEM_DATA:['Sem data','neutral']};
const stkData=v=>v?v.split('-').reverse().join('/'):'—';
const stkLotes=(c,u)=>STK_LT.filter(l=>l.c===c&&(u?l.u===u:stkUnids().includes(l.u))&&l.q>0.00001);
/* Lote automático (FEFO): saída tira primeiro o saldo sem lote, depois o lote que vence antes, e o vencido por último (com aviso); a perda tira primeiro o vencido */
function stkFefo(c,u,q,tipo){const i=STK(c);const lots=stkLotes(c,u).slice();const semLote=Math.max(0,(i.s[u]||0)-lots.reduce((s,l)=>s+l.q,0));const venc=lots.filter(l=>stkDias(l.v)<0).sort((a,b)=>a.v<b.v?-1:1),bons=lots.filter(l=>stkDias(l.v)>=0).sort((a,b)=>a.v<b.v?-1:1);
 const ordem=tipo==='PERDA'?[...venc.map(l=>({l})),{sem:semLote},...bons.map(l=>({l}))]:[{sem:semLote},...bons.map(l=>({l})),...venc.map(l=>({l}))];const partes=[];let resta=q;
 ordem.forEach(o=>{if(resta<=0.00001)return;const disp=o.l?o.l.q:o.sem;if(disp<=0.00001)return;const t=Math.min(disp,resta);partes.push({l:o.l?o.l.l:null,v:o.l?o.l.v:null,q:Math.round(t*1000)/1000,venc:o.l?stkDias(o.l.v)<0:false});resta-=t});
 if(resta>0.00001)partes.push({l:null,v:null,q:Math.round(resta*1000)/1000,falta:true});return partes}
function stkAplica(mv,sinal){/* sinal 1 aplica, -1 desfaz; atualiza saldos e lotes */
 const k=mv.tipo==='ESTORNO'?0:STK_TP[mv.tipo][1];mv.it.forEach(x=>{const i=STK(x.c);const d=k*x.q*sinal;i.s[mv.u]=Math.round(((i.s[mv.u]||0)+d)*1000)/1000;if(x.l){let lt=STK_LT.find(l=>l.c===x.c&&l.l===x.l&&l.u===mv.u);if(!lt&&d>0){lt={c:x.c,l:x.l,v:x.v||'',u:mv.u,q:0};STK_LT.push(lt)}if(lt)lt.q=Math.round(Math.max(0,lt.q+d)*1000)/1000}})}

