let STK_PF='';
VIEWS['estoque-pedidos']=()=>{const l=STK_PD.filter(p=>!STK_PF||p.st===STK_PF);
 return `${pageHead('Estoque','Pedidos de compra','Rascunho, aprovação, envio, recebimento parcial ou total (com nota fiscal, lote e validade), encerramento e cancelamento. Dados de exemplo.',`${rulesBtn('Pedidos de compra')}${stkTrilhaBtn()}<button class="btn" onclick="${stkPode()?'stkNovoPedido()':'stkBloq()'}">${I.plus} Novo pedido</button>`)}
 ${stkComo()}
 <div class="filters">${[['','Todos'],...Object.entries(STK_PDST).map(([k,[t]])=>[k,t])].map(([k,t])=>chip(t+(k?' ('+STK_PD.filter(p=>p.st===k).length+')':''),STK_PF===k,`STK_PF='${k}';reView()`)).join('')}</div>
 ${tabela(['Pedido','Fornecedor','Criado','Previsão','Itens','Valor','Recebido','Situação'],l.map(p=>{const tu=p.it.reduce((s,x)=>s+x.e*STK(x.c).fator,0),ru=p.it.reduce((s,x)=>s+x.r,0);const atras=stkAtras(p);return `<tr class="clk" onclick="stkPedido('${p.n}')">${td('Pedido',`<span class="mono">${p.n}</span>`)}${td('Fornecedor',esc(p.forn))}${td('Criado',p.criado+' · '+p.por)}${td('Previsão',p.prev?(atras?`<span class="prazo-err">${p.prev} · atrasado ${atras} dia(s)</span>`:p.prev):'—')}${td('Itens',p.it.length)}${td('Valor',fmt(stkPdTotal(p)))}${td('Recebido',tu?Math.round(ru/tu*100)+'%':'—')}${td('Situação',`<span class="badge ${STK_PDST[p.st][1]}">${STK_PDST[p.st][0]}</span>`)}</tr>`}),'Nenhum pedido')}
 ${piada(88,{todos:'Pedido de compra enviado é promessa; pedido recebido é amor; pedido parcial é relacionamento complicado.'})}`};
function stkPedido(n){const p=STK_PD.find(x=>x.n===n);const f=STK_FORN.find(x=>x.n===p.forn)||{};const ab=p.st==='ABERTO'||p.st==='PARCIAL';
 openDrawer('Pedido de compra '+p.n,`${kvs([['Fornecedor',esc(p.forn)+(f.cnpj?' · CNPJ '+f.cnpj:'')],['Contato',f.tel||'—'],['Situação',`<span class="badge ${STK_PDST[p.st][1]}">${STK_PDST[p.st][0]}</span>`],['Criado',p.criado+' por '+p.por],['Aprovado',p.aprov||(stkPdTotal(p)>2000?'precisa de aprovação (acima de R$ 2.000)':'não precisa (até R$ 2.000)')],['Enviado',p.env||'—'],['Entrega desejada até',p.prev||'—'],['Condição de pagamento',p.cond||'—'],p.motivo?['Motivo',esc(p.motivo)]:null])}
 <h4 style="margin-top:10px">Itens</h4>${tabela(['Material','Embalagem','Qtd (emb.)','Unidades','Recebido','Preço por emb.','Total'],p.it.map(x=>{const i=STK(x.c);return `<tr>${td('Material',esc(i.n))}${td('Embalagem',i.emb||i.un)}${td('Qtd',p.st==='RASCUNHO'?`<input class="in stk-in" inputmode="numeric" value="${x.e}" onchange="stkPdQtd('${p.n}','${x.c}',this.value)" aria-label="Quantidade de ${esc(i.n)}">`:x.e)}${td('Unidades',stkQ(x.e*i.fator))}${td('Recebido',stkQ(x.r)+(p.st==='ENCERRADO'&&x.r<x.e*i.fator?' <small class="tl">saldo cancelado no encerramento</small>':''))}${td('Preço',fmt(x.ce))}${td('Total',fmt(x.e*x.ce))}</tr>`}))}<p style="text-align:right;margin-top:6px"><b>Total do pedido: ${fmt(stkPdTotal(p))}</b></p>
 ${p.recs&&p.recs.length?`<h4 style="margin-top:10px">Recebimentos</h4><div class="at-list">${p.recs.map(r=>`<div class="at-row"><div class="grow"><b>${esc(r.nf)}</b><small>${r.d} · recebido por ${esc(r.por)} · entrada no estoque e conta a pagar no Financeiro</small></div></div>`).join('')}</div>`:''}
 <div class="row" style="margin-top:12px;gap:6px;flex-wrap:wrap"><button class="btn ghost" onclick="stkPdImprimir('${p.n}')">${I.print} Imprimir ou PDF</button>
 ${p.st==='RASCUNHO'?`<button class="btn" onclick="stkPdEnviar('${p.n}')">Enviar pedido</button><button class="btn ghost" onclick="stkPdCancelar('${p.n}')">Descartar rascunho</button>`:''}
 ${p.st==='APROVAR'?`<button class="btn" onclick="stkPdAprovar('${p.n}')">Aprovar e enviar</button><button class="btn ghost" onclick="stkPdCancelar('${p.n}')">Cancelar</button>`:''}
 ${ab?`<button class="btn" onclick="stkPdReceber('${p.n}')">Receber itens</button><button class="btn sec" onclick="stkPdEncerrar('${p.n}')">Encerrar</button>${p.st==='ABERTO'?`<button class="btn ghost" onclick="stkPdCancelar('${p.n}')">Cancelar pedido</button>`:''}`:''}</div>
 ${p.st==='RASCUNHO'?'<p class="tl" style="margin-top:8px">Depois de enviado, o pedido conta como "em pedido" e o ressuprimento não sugere comprar de novo.</p>':''}`)}
function stkPdQtd(n,c,v){const p=STK_PD.find(x=>x.n===n);const x=p.it.find(y=>y.c===c);x.e=Math.max(0,parseInt(v,10)||0);stkPedido(n)}
function stkPdEnviar(n){if(!stkPode())return stkBloq();const p=STK_PD.find(x=>x.n===n);if(!p.prev)p.prev=String(4+((STK_FORN.find(f=>f.n===p.forn)||{}).prazo||5)).padStart(2,'0')+'/11';if(stkPdTotal(p)>2000&&stkPerfil()!=='admin'){p.st='APROVAR';stkAud(`Pedido ${n} (${fmt(stkPdTotal(p))}) enviado para aprovação`);closeDrawer();reView();toast('Acima de R$ 2.000,00: o pedido foi para aprovação (quem monta não aprova, exceto o Administrador)','warn');return}p.st='ABERTO';p.env='04/11';if(stkPerfil()==='admin'&&stkPdTotal(p)>2000)p.aprov=STK_USU;stkAud(`Pedido ${n} enviado ao fornecedor`);closeDrawer();reView();toast(`Pedido ${n} enviado a ${p.forn}; conta como "em pedido" no ressuprimento`)}
function stkPdAprovar(n){const p=STK_PD.find(x=>x.n===n);if(p.por===STK_USU&&stkPerfil()!=='admin'){toast('Quem monta o pedido não aprova: outra pessoa (ou o Administrador)','warn');return}if(!stkPode())return stkBloq();p.st='ABERTO';p.env='04/11';p.aprov=STK_USU;stkAud(`Pedido ${n} aprovado e enviado`);closeDrawer();reView();toast('Pedido aprovado por '+STK_USU+' e enviado')}
function stkPdCancelar(n){if(!stkPode())return stkBloq();const p=STK_PD.find(x=>x.n===n);if(p.it.some(x=>x.r>0)){toast('Já recebeu parte: use Encerrar','warn');return}f2Motivo((p.st==='RASCUNHO'?'Descartar rascunho ':'Cancelar pedido ')+n,'O pedido fica no histórico como cancelado, com o motivo. Nada é apagado.',m=>{p.st='CANCELADO';p.motivo=m;stkAud(`Pedido ${n} cancelado. Motivo: ${m}`);closeDrawer();reView();toast('Pedido '+n+' cancelado','warn')},'Cancelar pedido','warn')}
function stkPdEncerrar(n){const p=STK_PD.find(x=>x.n===n);f2Motivo('Encerrar pedido '+n,'O que não chegou é cancelado e deixa de contar como "em pedido". O que já foi recebido continua.',m=>{p.st='ENCERRADO';p.motivo=m;stkAud(`Pedido ${n} encerrado com saldo cancelado. Motivo: ${m}`);closeDrawer();reView();toast('Pedido encerrado; saldo não recebido cancelado')},'Encerrar')}
function stkPdReceber(n){if(!stkPode())return stkBloq();const p=STK_PD.find(x=>x.n===n);openModal(`${mh('Receber itens · '+p.n)}<div class="mb"><div class="formgrid"><div class="field"><label>Nota fiscal ou documento <span class="req">*</span></label><input class="in" id="stkRNF" placeholder="NF 000000"></div><div class="field"><label>Valor da nota</label><input class="in" id="stkRV" inputmode="decimal" placeholder="0,00"></div></div>${p.it.map((x,ix)=>{const i=STK(x.c);const falta=Math.max(0,x.e*i.fator-x.r);return `<div class="stk-linha"><div class="field"><label>${esc(i.n)}</label><small>pedido ${stkQ(x.e*i.fator)} · recebido ${stkQ(x.r)} · falta ${stkQ(falta)}</small></div><div class="field"><label>Chegou</label><input class="in" id="stkRQ${ix}" inputmode="decimal" value="${falta}"></div><div class="field"><label>Lote</label><input class="in" id="stkRL${ix}" placeholder="Lote"></div><div class="field"><label>Validade</label><input class="in" id="stkRVal${ix}" type="date"></div><span></span></div>`}).join('')}<p class="tl" style="margin-top:8px">Entra no estoque como Entrada (custo médio atualizado) e a nota vira conta a pagar no Financeiro, para outra pessoa pagar.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="stkPdReceberOk('${n}')">Registrar recebimento</button></div>`,'wide')}
function stkPdReceberOk(n){const p=STK_PD.find(x=>x.n===n);const nf=$('#stkRNF').value.trim();if(!nf){toast('Informe a nota fiscal','warn');return}const it=[];let semVal=false;p.it.forEach((x,ix)=>{const q=parseFloat(($('#stkRQ'+ix).value||'0').replace(',','.'))||0;if(q<=0)return;const l=$('#stkRL'+ix).value.trim(),v=$('#stkRVal'+ix).value;if(l&&!v)semVal=true;it.push({c:x.c,q,l:l||undefined,v:v||undefined,cu:x.ce/STK(x.c).fator,ref:x})});if(semVal){toast('Lote informado precisa da validade','warn');return}if(!it.length){toast('Nenhuma quantidade informada','warn');return}it.forEach(x=>{x.ref.r+=x.q;delete x.ref});
 const mv={n:STK_SEQ++,tipo:'ENTRADA',d:'04/11 '+hhmm(new Date()),u:10,forn:p.forn,doc:nf,obs:'Pedido '+p.n,it,por:STK_USU,orig:'pedido '+p.n};it.forEach(x=>{const i=STK(x.c);const s=Object.values(i.s).reduce((a,b)=>a+b,0);i.custo=Math.round((s*i.custo+x.q*x.cu)/(s+x.q)*10000)/10000});STK_MV.unshift(mv);stkAplica(mv,1);
 const tudo=p.it.every(x=>x.r>=x.e*STK(x.c).fator-0.0001);p.st=tudo?'RECEBIDO':'PARCIAL';(p.recs=p.recs||[]).push({d:'04/11',nf,por:STK_USU});const val=parseFloat(($('#stkRV').value||'').replace(',','.'))||Math.round(it.reduce((s,x)=>s+x.q*x.cu,0)*100)/100;
 if(typeof CONTAS!=='undefined')CONTAS.push({t:'pagar',por:STK_USU,q:p.forn,tipo:'fornecedor',cat:'3.3',ref:nf+' · pedido '+p.n,venc:'04/12',v:val,s:'A vencer',rec:'unica',fixo:false,anx:[nf+'.pdf']});
 stkAud(`Pedido ${n}: recebimento ${nf} (${it.length} item(ns)); conta a pagar de ${fmt(val)} criada`);closeModal();closeDrawer();reView();retorno('ok',tudo?'Pedido recebido':'Entrega parcial registrada',`Entrada nº ${mv.n} no estoque. ${nf} virou conta a pagar de ${fmt(val)} no Financeiro (lançada por ${STK_USU}; outra pessoa paga).${tudo?'':' O que falta continua "em pedido".'}`,[{l:'Abrir A pagar',on:"FN_ABA='pagar';location.hash='financeiro'"},{l:'Fechar',sec:true}])}
function stkPdImprimir(n){const p=STK_PD.find(x=>x.n===n);const f=STK_FORN.find(x=>x.n===p.forn)||{};openModal(`${mh('Pedido de compra '+p.n)}<div class="mb"><div class="stk-folha">${p.st==='RASCUNHO'?'<div class="alert warn"><span><b>Rascunho:</b> este pedido ainda não foi enviado.</span></div>':''}<div class="row" style="justify-content:space-between;flex-wrap:wrap;gap:8px;border-bottom:2px solid var(--accent);padding-bottom:8px;margin-bottom:8px"><b>DeoClinic · Unidade 10 · Central</b><span class="mono">${p.n}</span></div>${kvs([['Fornecedor',esc(p.forn)+(f.cnpj?' · '+f.cnpj:'')],['Data do pedido',p.env||p.criado],['Entrega desejada até',p.prev||'—'],['Condição de pagamento',p.cond||'—'],['Solicitante',p.por]])}${tabela(['Código','Material','Embalagem','Quantidade','Total em unidades','Preço por emb.','Total'],p.it.map(x=>{const i=STK(x.c);return `<tr>${[i.c,esc(i.n),i.emb||i.un,x.e,stkQ(x.e*i.fator),fmt(x.ce),fmt(x.e*x.ce)].map((v,j)=>td(['Código','Material','Embalagem','Quantidade','Unidades','Preço','Total'][j],v)).join('')}</tr>`}))}<p style="text-align:right;margin-top:6px"><b>Total do pedido: ${fmt(stkPdTotal(p))}</b></p><p class="tl">Favor confirmar o recebimento deste pedido e informar o prazo de entrega. Na nota fiscal, cite o número ${p.n}.</p><div class="row" style="justify-content:space-around;margin-top:24px;gap:16px;flex-wrap:wrap"><span class="tl">______________________<br>Responsável pelas compras</span><span class="tl">______________________<br>Aprovação</span></div></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button><button class="btn" onclick="toast('Pedido enviado para imprimir ou salvar em PDF')">${I.print} Imprimir ou PDF</button></div>`,'wide')}
function stkNovoPedido(){openModal(`${mh('Novo pedido de compra')}<div class="mb"><div class="field"><label>Fornecedor</label><select class="in" id="stkNPF">${STK_FORN.map(f=>`<option>${f.n}</option>`).join('')}</select></div><p class="tl">O pedido nasce em rascunho com os itens do fornecedor que estão abaixo do máximo; ajuste as quantidades na ficha do pedido.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="stkNovoPedidoOk()">Criar rascunho</button></div>`)}
function stkNovoPedidoOk(){const f=$('#stkNPF').value;const it=STK_IT.filter(i=>i.forn===f&&i.ativo).map(i=>({i,s:stkSugestao(i,'maximo')})).filter(x=>x.s.emb>0).map(x=>({c:x.i.c,e:x.s.emb,ce:Math.round(x.i.custo*x.i.fator*100)/100,r:0}));const p={n:'PC-00'+(STK_PDSEQ++),forn:f,st:'RASCUNHO',criado:'04/11',por:STK_USU,prev:'',cond:(STK_FORN.find(x=>x.n===f)||{}).cond,it:it.length?it:[{c:STK_IT.find(i=>i.forn===f).c,e:1,ce:Math.round(STK_IT.find(i=>i.forn===f).custo*STK_IT.find(i=>i.forn===f).fator*100)/100,r:0}]};STK_PD.unshift(p);stkAud('Pedido '+p.n+' criado em rascunho');closeModal();reView();stkPedido(p.n)}

