let STK_IVA='INV-2026-11';
const stkIvItens=iv=>STK_IT.filter(i=>i.ativo&&(iv.escopo==='todos'||(iv.escopo==='A'?stkABC(iv.u).l.some(x=>x.i.c===i.c&&x.cl==='A'):i.cat===iv.escopo)));
VIEWS['estoque-inventario']=()=>{const iv=STK_IV.find(x=>x.n===STK_IVA)||STK_IV[0];const its=stkIvItens(iv);const cont=its.filter(i=>iv.cont[i.c]!=null);const dif=cont.filter(i=>Math.abs(iv.cont[i.c]-(i.s[iv.u]||0))>0.0001);const mais=dif.reduce((s,i)=>s+Math.max(0,iv.cont[i.c]-(i.s[iv.u]||0))*i.custo,0),menos=dif.reduce((s,i)=>s+Math.max(0,(i.s[iv.u]||0)-iv.cont[i.c])*i.custo,0);const ab=iv.st==='ABERTO';
 return `${pageHead('Estoque','Inventário','Contagem de conferência ou implantação do saldo inicial: folha de contagem, contagem às cegas, digitação com salvamento automático e ajuste automático das diferenças. Dados de exemplo.',`${rulesBtn('Inventário')}${stkTrilhaBtn()}<button class="btn" onclick="${stkPode()?'stkNovoInv()':'stkBloq()'}">${I.plus} Novo inventário</button>`)}
 ${stkComo()}
 <div class="row" style="gap:6px;flex-wrap:wrap;margin-bottom:12px">${STK_IV.map(x=>chip(`${x.n} · ${x.st==='ABERTO'?'em contagem':x.st==='APLICADO'?'aplicado':'cancelado'}`,STK_IVA===x.n,`STK_IVA='${x.n}';reView()`)).join('')}</div>
 <div class="card at-card"><h3>${esc(iv.desc)} ${info('Itens não contados não mudam. Ao aplicar, sobras saem como Ajuste (+) e faltas como Ajuste (−), num lançamento ligado ao inventário.')}</h3>${kvs([['Tipo',iv.tipo],['Unidade',unidNome(iv.u)],['Escopo',iv.escopo==='todos'?'todos os itens':iv.escopo==='A'?'itens da curva A':iv.escopo],['Aberto',iv.criado+' por '+iv.por],['Situação',`<span class="badge ${ab?'warn':iv.st==='APLICADO'?'ok':'neutral'}">${ab?'Em contagem':iv.st==='APLICADO'?'Aplicado':'Cancelado'}</span>${iv.aplic?' · '+iv.aplic:''}`],iv.res?['Resultado',iv.res]:null])}
 ${ab?`<div class="mini" style="margin-top:10px">${miniKpi('Itens contados',cont.length+' de '+its.length,'')}${miniKpi('Com diferença',dif.length,'',dif.length?'warn':'ok')}${miniKpi('Contado a mais',fmt(mais),'')}${miniKpi('Contado a menos',fmt(menos),'',menos?'err':'')}</div>
 <div class="filters" style="margin-top:10px"><label class="switchrow" style="border:0;padding:0;gap:8px"><span>Contagem às cegas ${info('Esconde o saldo do sistema de quem conta, para a contagem não ser influenciada.')}</span><span class="switch"><input type="checkbox" ${iv.cegas?'checked':''} onchange="STK_IV.find(x=>x.n==='${iv.n}').cegas=this.checked;reView()"><span class="tr"></span></span></label><button class="btn sm sec" onclick="stkFolha('${iv.n}')" style="margin-left:auto">${I.print} Imprimir folha de contagem</button></div>
 ${tabela(['Código','Material','Unidade','Local',iv.cegas?null:'Sistema','Contagem',iv.cegas?null:'Diferença','Salvamento'].filter(Boolean),its.map(i=>{const c=iv.cont[i.c];const s=i.s[iv.u]||0;const d=c!=null?c-s:null;return `<tr>${td('Código',`<span class="mono">${i.c}</span>`)}${td('Material',esc(i.n))}${td('Unidade',i.un)}${td('Local',i.loc)}${iv.cegas?'':td('Sistema',stkQ(s))}${td('Contagem',`<input class="in stk-in" inputmode="decimal" value="${c??''}" aria-label="Contagem de ${esc(i.n)}" onchange="stkContar('${iv.n}','${i.c}',this.value)">`)}${iv.cegas?'':td('Diferença',d==null?'—':Math.abs(d)<0.0001?'<span class="badge ok">bate</span>':`<span class="${d<0?'f2-menos':'f2-mais'}">${d>0?'+':'−'} ${stkQ(Math.abs(d))}</span>`)}${td('Salvamento',c!=null?'<span class="tl">salvo</span>':'<span class="tl">não contado</span>')}</tr>`}))}
 <p class="tl" style="margin-top:6px">Cada quantidade é salva ao sair do campo. As diferenças comparam com o saldo atual e mudam se houver entrada ou saída antes de aplicar.</p>
 <div class="row" style="margin-top:12px;gap:8px;flex-wrap:wrap"><button class="btn" onclick="stkAplicarInv('${iv.n}')">Aplicar inventário</button><button class="btn ghost" onclick="stkCancelarInv('${iv.n}')">Cancelar inventário</button><span class="tl">${cont.length} itens contados, ${dif.length} com diferença: sobras entram como ajuste (+) e faltas como ajuste (−).</span></div>`:''}</div>
 ${piada(89,{todos:'Inventário é a hora da verdade: o sistema diz 32, a prateleira diz 30 e o álcool evaporou sem deixar recado.'})}`};
function stkContar(n,c,v){if(!stkPode()){stkBloq();reView();return}const iv=STK_IV.find(x=>x.n===n);if(v.trim()===''){delete iv.cont[c]}else{const q=parseFloat(v.replace(',','.'));if(isNaN(q)||q<0){toast('Contagem inválida','warn');return}iv.cont[c]=q}iv.contPor=STK_USU;reView()}
function stkAplicarInv(n){if(!stkPode())return stkBloq();const iv=STK_IV.find(x=>x.n===n);if((iv.contPor||iv.por)===STK_USU&&stkPerfil()!=='admin'){toast('Quem contou não aplica: outra pessoa do estoque confere e aplica (ou o Administrador)','warn');return}const its=stkIvItens(iv).filter(i=>iv.cont[i.c]!=null&&Math.abs(iv.cont[i.c]-(i.s[iv.u]||0))>0.0001);
 modalOk('Aplicar '+iv.n,`<p style="font-size:14px">${its.length} item(ns) com diferença. As sobras entram como Ajuste (+) e as faltas como Ajuste (−), num lançamento ligado a este inventário. Itens não contados não mudam.</p>`,'Aplicar inventário',`stkAplicarInvOk('${n}')`)}
function stkAplicarInvOk(n){const iv=STK_IV.find(x=>x.n===n);const its=stkIvItens(iv).filter(i=>iv.cont[i.c]!=null&&Math.abs(iv.cont[i.c]-(i.s[iv.u]||0))>0.0001);const mais=its.filter(i=>iv.cont[i.c]>(i.s[iv.u]||0)),menos=its.filter(i=>iv.cont[i.c]<(i.s[iv.u]||0));const tipoMais=iv.tipo.startsWith('Implanta')?'SALDO_INICIAL':'AJUSTE_MAIS';
 [[tipoMais,mais],['AJUSTE_MENOS',menos]].forEach(([t,l])=>{if(!l.length)return;const it=[];l.forEach(i=>{const d=Math.abs(iv.cont[i.c]-(i.s[iv.u]||0));if(t==='AJUSTE_MENOS')stkFefo(i.c,iv.u,d,'PERDA').forEach(p=>{if(!p.falta)it.push({c:i.c,q:p.q,l:p.l||undefined})});else it.push({c:i.c,q:d})});const mv={n:STK_SEQ++,tipo:t,d:'04/11 '+hhmm(new Date()),u:iv.u,doc:iv.n,obs:'Inventário '+iv.n+': '+iv.desc,it,por:STK_USU,orig:'inventário '+iv.n};STK_MV.unshift(mv);stkAplica(mv,1)});
 iv.st='APLICADO';iv.aplic=STK_USU+' · 04/11 '+hhmm(new Date());iv.res=`${Object.keys(iv.cont).length} itens contados, ${its.length} com diferença`;stkAud(`Inventário ${n} aplicado: ${its.length} ajuste(s)`);reView();toast('Inventário aplicado: '+its.length+' ajuste(s) lançado(s)')}
function stkCancelarInv(n){const iv=STK_IV.find(x=>x.n===n);f2Motivo('Cancelar '+n,'Descarta as contagens. Nenhum saldo é alterado; o inventário fica no histórico como cancelado.',m=>{iv.st='CANCELADO';iv.res='Cancelado: '+m;stkAud(`Inventário ${n} cancelado. Motivo: ${m}`);reView();toast('Inventário cancelado; nenhum saldo alterado','warn')},'Cancelar inventário','warn')}
function stkNovoInv(){openModal(`${mh('Novo inventário')}<div class="mb"><div class="formgrid"><div class="field"><label>Descrição</label><input class="in" id="stkIvD" value="Contagem de conferência · dezembro"></div><div class="field"><label>Tipo</label><select class="in" id="stkIvT"><option>Contagem de conferência</option><option>Implantação do saldo inicial</option></select></div><div class="field"><label>Unidade</label><select class="in" id="stkIvU">${[10,12,14].map(u=>`<option value="${u}">${unidNome(u)}</option>`).join('')}</select></div><div class="field"><label>Itens</label><select class="in" id="stkIvE"><option value="A">Só a curva A</option><option value="todos">Todos os itens</option>${[...new Set(STK_IT.map(i=>i.cat))].map(c=>`<option>${c}</option>`).join('')}</select></div></div><div class="switchrow"><span>Contagem às cegas<small>Esconde o saldo do sistema de quem conta.</small></span><label class="switch"><input type="checkbox" id="stkIvC" checked><span class="tr"></span></label></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="stkNovoInvOk()">Abrir inventário</button></div>`)}
function stkNovoInvOk(){const n='INV-2026-'+(11+STK_IV.filter(x=>x.n.startsWith('INV-2026-1')).length);const iv={n,desc:$('#stkIvD').value||'Contagem',tipo:$('#stkIvT').value,st:'ABERTO',u:+$('#stkIvU').value,cegas:$('#stkIvC').checked,escopo:$('#stkIvE').value,por:STK_USU,criado:'04/11',cont:{}};STK_IV.unshift(iv);STK_IVA=n;stkAud('Inventário '+n+' aberto');closeModal();reView();toast('Inventário '+n+' aberto: imprima a folha e conte')}
function stkFolha(n){const iv=STK_IV.find(x=>x.n===n);const its=stkIvItens(iv);openModal(`${mh('Folha de contagem · '+iv.n)}<div class="mb"><div class="stk-folha">${kvs([['Inventário',esc(iv.desc)],['Itens nesta folha',its.length],['Aberto em',iv.criado],['Data da contagem','____/____/________']])}<p class="tl" style="margin:8px 0">Conte cada item e escreva a quantidade na unidade indicada. Item não encontrado: escreva 0.</p>${tabela(['Código','Material','Unidade','Local',iv.cegas?null:'Sistema','Contagem'].filter(Boolean),its.map(i=>`<tr>${td('Código',i.c)}${td('Material',esc(i.n))}${td('Unidade',i.un)}${td('Local',i.loc)}${iv.cegas?'':td('Sistema',stkQ(i.s[iv.u]||0))}${td('Contagem','________')}</tr>`))}<div class="row" style="justify-content:space-around;margin-top:20px;gap:16px;flex-wrap:wrap"><span class="tl">______________________<br>Contado por</span><span class="tl">______________________<br>Conferido por</span></div></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button><button class="btn" onclick="toast('Folha de contagem enviada para imprimir')">${I.print} Imprimir folha</button></div>`,'wide')}

