let STK_REL='posicao';
VIEWS['estoque-relatorios']=()=>`${pageHead('Estoque','Relatórios do estoque','Posição do estoque, consumo por período e setor, consumo por procedimento, perdas, curva ABC, itens parados e compras por fornecedor. Dados de exemplo.',`${rulesBtn('Relatórios do estoque')}<button class="btn sec" onclick="toast('Relatório enviado para imprimir')">${I.print} Imprimir</button><button class="btn sec" onclick="toast('Planilha (CSV) exportada para o Excel')">Exportar planilha (CSV)</button>`)}
 ${stkUnidChips()}
 <div class="tabs" role="tablist">${[['posicao','Posição do estoque'],['consumo','Consumo por setor'],['procedimento','Consumo por procedimento ★'],['perdas','Perdas'],['abc','Curva ABC'],['parados','Itens parados'],['compras','Compras por fornecedor']].map(([k,t])=>`<button class="tab ${STK_REL===k?'active':''}" onclick="STK_REL='${k}';reView()">${t}</button>`).join('')}</div>
 ${['consumo','perdas','compras','procedimento'].includes(STK_REL)?filtroBarra({id:'stkrel',periodo:true,padrao:'mes',onchange:'reView()'}):''}
 ${stkRel()}`;
function stkRel(){const u=STK_U;
 if(STK_REL==='posicao'){const m={};STK_IT.filter(i=>i.ativo).forEach(i=>{const x=m[i.cat]=m[i.cat]||{n:0,com:0,rep:0,zer:0,v:0};x.n++;const s=stkSaldo(i,u);if(s>0)x.com++;const k=stkSit(i,u);if(k==='REPOR')x.rep++;if(k==='ZERADO')x.zer++;x.v+=s*i.custo});const tot=Object.values(m).reduce((s,x)=>s+x.v,0);
  return `<div class="card at-card"><h3>Valor em estoque por categoria <span class="tl">· hoje, pelo custo atual de cada item</span></h3>${tabela(['Categoria','Itens ativos','Com saldo','Para repor','Zerados','Valor','% do valor'],Object.entries(m).sort((a,b)=>b[1].v-a[1].v).map(([c,x])=>`<tr>${td('Categoria',c)}${td('Itens',x.n)}${td('Com saldo',x.com)}${td('Para repor',x.rep)}${td('Zerados',x.zer)}${td('Valor',fmt(x.v))}${td('%',f2pct(x.v/tot*100))}</tr>`))}<p class="tl" style="margin-top:8px">A planilha exportada traz todos os itens, com saldo, custo, valor, mínimo, máximo e situação.</p></div>`}
 if(STK_REL==='consumo'){const l=[['Sala de coleta',[['02035',2380],['01550',2010],['01556',2600],['03849',430]]],['Laboratório · bancadas',[['03963',13],['04188',3],['04133',1]]],['Sala de ultrassom',[['01542',1.6],['02219',58],['01581',12.3]]],['Consultórios 1 e 2',[['01576',620],['01619',290],['01581',12.4]]],['Sala de procedimentos',[['03738',640],['04178',40],['01512',0.2]]]];
  return `${l.map(([s,its])=>{const tot=its.reduce((a,[c,q])=>a+q*STK(c).custo,0);return `<div class="card at-card" style="margin-top:10px"><h3>${s} <span class="tl">· ${fmt(tot)} · ${periodoTexto('stkrel')}</span></h3>${tabela(['Código','Material','Quantidade','Valor','% do setor'],its.map(([c,q])=>`<tr>${td('Código',c)}${td('Material',esc(STK(c).n))}${td('Quantidade',stkQ(q))}${td('Valor',fmt(q*STK(c).custo))}${td('%',f2pct(q*STK(c).custo/tot*100))}</tr>`))}</div>`}).join('')}`}
 if(STK_REL==='procedimento'){const vol={'10101012':620,'40901122':180,'40901300':84,'40901467':96,'40901483':52,'40901530':70,'40101010':130,'20104090':88,'COLETA':2710};return `<div class="card at-card"><h3>Consumo de insumos por procedimento ★ ${info('Atendimentos finalizados × kit do procedimento. Mostra quanto cada linha de serviço gasta de material, e é o mesmo número usado no Custo e margem.')}</h3>${tabela(['Procedimento','Atendimentos','Custo do kit','Insumos no período','Custo e margem'],Object.keys(vol).map(p=>`<tr>${td('Procedimento',STK_KITNOME(p))}${td('Atendimentos',vol[p])}${td('Kit',fmt(stkKitCusto(p)))}${td('Insumos',fmt(stkKitCusto(p)*vol[p]))}${td('',p==='COLETA'?'<span class="tl">laboratório</span>':`<a href="#custos-procedimento" onclick="event.stopPropagation()">ver margem</a>`)}</tr>`))}</div>`}
 if(STK_REL==='perdas'){const l=STK_MV.filter(m=>m.tipo==='PERDA'||m.tipo==='AJUSTE_MENOS');return `<div class="card at-card"><h3>Perdas e ajustes (−) <span class="tl">· ${periodoTexto('stkrel')}</span></h3>${tabela(['Nº','Data','Tipo','Material','Lote','Qtd','Valor','Motivo'],l.flatMap(m=>m.it.map(x=>`<tr class="clk" onclick="stkMov(${m.n})">${td('Nº',m.n)}${td('Data',m.d)}${td('Tipo',STK_TP[m.tipo][0])}${td('Material',esc(STK(x.c).n))}${td('Lote',x.l||'—')}${td('Qtd',stkQ(x.q))}${td('Valor',fmt(x.q*STK(x.c).custo))}${td('Motivo',esc(m.obs))}</tr>`)),'Nenhuma perda no período')}<p class="tl" style="margin-top:8px">Outubro: R$ 48,30 em ajustes de inventário e R$ 40,58 em vencidos. Perda acima de R$ 500,00 abre não conformidade na Gestão da qualidade.</p></div>`}
 if(STK_REL==='abc'){const a=stkABC(u);return `<div class="card at-card"><h3>Curva ABC ${info('Classifica os itens pelo valor consumido por mês (consumo médio × custo). A: os itens que somam 80% do valor, que merecem controle mais rigoroso e contagem frequente. B: os próximos 15%. C: os 5% restantes.')}</h3>${tabela(['Classe','Código','Material','Consumo por mês','Valor por mês','% acumulado'],a.l.map(x=>`<tr class="clk" onclick="stkFicha('${x.i.c}')">${td('Classe',`<b>${x.cl}</b>`)}${td('Código',x.i.c)}${td('Material',esc(x.i.n))}${td('Consumo/mês',stkQ(stkCm(x.i,u)))}${td('Valor/mês',fmt(x.v))}${td('% acumulado',f2pct(x.ac))}</tr>`))}<p class="tl" style="margin-top:8px">${STK_IT.filter(i=>i.ativo&&(!i.cm||!i.custo)).length} itens ativos sem consumo ou sem custo ficam fora da curva.</p></div>`}
 if(STK_REL==='parados'){const l=STK_IT.filter(i=>i.cm===0&&stkSaldo(i,u)>0);return `<div class="card at-card"><h3>Sem saída há mais de 90 dias</h3><p class="tl" style="margin-bottom:8px">${l.length} itens com saldo e sem saída há mais de 90 dias, somando ${fmt(l.reduce((s,i)=>s+stkSaldo(i,u)*i.custo,0))} parados no estoque. Avalie reduzir o máximo, remanejar ou devolver.</p>${tabela(['Código','Material','Saldo','Valor','Última saída','Última entrada'],l.map(i=>`<tr class="clk" onclick="stkFicha('${i.c}')">${td('Código',i.c)}${td('Material',esc(i.n))}${td('Saldo',stkQ(stkSaldo(i,u)))}${td('Valor',fmt(stkSaldo(i,u)*i.custo))}${td('Última saída',i.c==='03426'?'08/03/2026':'nenhuma lançada')}${td('Última entrada',i.c==='03426'?'05/01/2026 (saldo inicial)':'05/01/2026 (saldo inicial)')}</tr>`))}</div>`}
 const atr=STK_PD.filter(p=>p.n==='PC-0044'&&(p.st==='ABERTO'||p.st==='PARCIAL'));const fs={};STK_PD.filter(p=>p.st!=='RASCUNHO'&&p.st!=='CANCELADO').forEach(p=>{const x=fs[p.forn]=fs[p.forn]||{n:0,v:0,rec:0};x.n++;x.v+=stkPdTotal(p);x.rec+=(p.recs||[]).length});
 return `<div class="grid g2"><div class="card at-card"><h3>Pedidos com entrega atrasada</h3>${tabela(['Pedido','Fornecedor','Situação','Enviado em','Prevista para','Atraso'],atr.map(p=>`<tr class="clk" onclick="stkPedido('${p.n}')">${td('Pedido',p.n)}${td('Fornecedor',esc(p.forn))}${td('Situação',STK_PDST[p.st][0])}${td('Enviado',p.env)}${td('Prevista',p.prev)}${td('Atraso','<span class="prazo-err">7 dias</span>')}</tr>`),'Nenhum pedido atrasado')}</div><div class="card at-card"><h3>Recebido por fornecedor</h3>${tabela(['Fornecedor','Pedidos enviados','Recebimentos','Valor'],Object.entries(fs).map(([f,x])=>`<tr>${td('Fornecedor',esc(f))}${td('Pedidos',x.n)}${td('Recebimentos',x.rec)}${td('Valor',fmt(x.v))}</tr>`))}</div></div>`}

/* ---------- Guias e regras de cada tela ---------- */
GUIDES.estoque=['Escolha o almoxarifado (unidade) no alto. Os números contam a situação dos itens, o valor em estoque e a compra sugerida; clique para abrir a lista.','"Para comprar agora" e "Previsão pela agenda" mostram o que acaba primeiro, inclusive pelos kits dos atendimentos marcados.','Use Lançar saída ou Lançar entrada para o dia a dia; validades e pedidos aguardando ficam logo abaixo.'];
GUIDES['estoque-itens']=['Busque pelo código ou nome e filtre por categoria ou situação.','Clique no item para ver a ficha: saldo por unidade, lotes, kits que usam o item e o Kardex com todo o histórico.','Use "Preencher mín/máx sugeridos" ou "Editar mín/máx em lista" para vários itens de uma vez; sem mínimo e máximo o item não entra no ressuprimento.'];
GUIDES['estoque-lancar']=['Escolha o tipo (saída, entrada, devolução, perda, ajuste, saldo inicial ou transferência), o almoxarifado e o setor ou fornecedor.','Inclua quantos itens quiser. Na saída, deixe o lote em Automático: o sistema tira primeiro o que vence antes e avisa se usar lote vencido.','Lançou errado? Abra o lançamento em Movimentações e use Estornar, com o motivo. Em Baixas automáticas, veja os kits baixados pelos atendimentos.'];
GUIDES['estoque-validades']=['Veja os lotes vencidos, os que vencem em até 30 dias e os em alerta (o prazo do alerta é configurável).','Registre a perda do lote vencido: o lançamento já vem preenchido.','Lote perto de vencer na Central? Transfira para a unidade que consome mais.'];
GUIDES['estoque-ressuprimento']=['Escolha o critério: itens que chegaram ao mínimo ou todo item abaixo do máximo. Ligue a agenda para somar o consumo dos atendimentos marcados.','Desmarque o que não quer comprar e ajuste as embalagens: o que já está em pedido já foi descontado.','Gere os pedidos: um rascunho por fornecedor. Imprima o relatório de compra se precisar.'];
GUIDES['estoque-pedidos']=['Abra o rascunho, revise as quantidades e clique em Enviar pedido. Acima de R$ 2.000,00 outra pessoa aprova antes.','Quando a compra chegar, use Receber itens: informe a nota fiscal, o que chegou, o lote e a validade. A nota vira conta a pagar no Financeiro.','O que não vai chegar: Encerrar (cancela o saldo). Pedido sem recebimento: Cancelar, com motivo.'];
GUIDES['estoque-inventario']=['Abra um inventário (conferência ou saldo inicial), escolha a unidade e os itens (por exemplo, só a curva A).','Imprima a folha de contagem, conte e digite: cada número é salvo ao sair do campo. Às cegas, quem conta não vê o saldo do sistema.','Outra pessoa confere e aplica: sobras viram ajuste (+), faltas ajuste (−). Itens não contados não mudam.'];
GUIDES['estoque-relatorios']=['Escolha o relatório nas abas e o período quando houver.','Posição, consumo por setor e por procedimento, perdas, curva ABC, parados e compras por fornecedor (com atrasos).','Imprima ou exporte a planilha (CSV) para o Excel.'];
REGRAS['Estoque']={aba:'Estoque · painel',itens:[['Escopo','Um só estoque multiunidade (almoxarifado por unidade) para clínica, imagem e laboratório; no Clinicas eram dois módulos paralelos (estoque e farmácia) sem unidade.'],['Situação','OK, Repor (no mínimo), Zerado, Acima do máximo, Sem mín/máx, Inativo; calculada pelo saldo da unidade.'],['Valor','Saldo × custo médio (configurável: último custo).'],['Agenda ★','Previsão de consumo dos kits pelos atendimentos marcados nos próximos 14 dias.'],['Curva ABC','A = 80% do valor consumido por mês; B = 15%; C = 5%.']]};
REGRAS['Itens do estoque']={aba:'Estoque · itens',itens:[['Cadastro','Código único, nome, unidade, categoria, fornecedor, embalagem de compra e fator; o saldo começa zerado.'],['Mín/máx','Por item e unidade; sugerido pelo consumo médio de 90 dias: mínimo cobre 15 dias, máximo 45 (configurável). Sem mín/máx não entra no ressuprimento.'],['Custo','Não é digitado: vem das entradas (custo médio ponderado).'],['Kardex','Todo o histórico do item com o saldo após cada lançamento; estorno aparece como lançamento novo.'],['Inativar','Tira do ressuprimento; o histórico continua.']]};
REGRAS['Entradas e saídas']={aba:'Estoque · lançamentos',itens:[['Tipos','Saída, Entrada, Devolução, Perda ou vencido, Ajuste (+), Ajuste (−), Saldo inicial, Transferência e Consumo automático; vários itens por lançamento.'],['Obrigatórios','Saída exige setor; entrada exige fornecedor e documento; perda e ajuste exigem motivo; lote informado exige validade.'],['Saldo','Saída sem saldo é bloqueada (configurável); tudo numa transação.'],['FEFO','Lote automático: saída tira primeiro o saldo sem lote, depois o que vence antes, e o vencido por último com aviso; a perda tira primeiro o vencido.'],['Estorno','Lançamento novo que anula o original (marcado como estornado), com motivo; nada é apagado. Bloqueado se o saldo não cobre.'],['Kit ★','Ao finalizar atendimento, ultrassom, ECG ou coleta, o kit do procedimento é baixado sozinho no setor da sala.'],['Transferência','Sai da origem no envio e entra no destino na confirmação; divergência vira ajuste com motivo.']]};
REGRAS['Lotes e validades']={aba:'Estoque · validades',itens:[['Situações','Vencido; vence em até 30 dias; alerta (padrão 60 dias, configurável); no prazo; sem data.'],['Saída','Lote vencido só sai por último e com aviso; perda tira primeiro os vencidos.'],['Ação','Registrar perda já preenchida; transferir para a unidade que consome mais.']]};
REGRAS['Ressuprimento']={aba:'Estoque · compras',itens:[['Critério','Itens que chegaram ao mínimo, ou todo item abaixo do máximo (configurável).'],['Quantidade','Compra até o máximo: máximo − (saldo + em pedido), arredondado para cima em embalagens.'],['Agenda ★','Opcional: soma o consumo dos kits da agenda acima do consumo normal.'],['Pedidos','Um rascunho por fornecedor; nada é enviado até alguém revisar e enviar.'],['Postos','Postos se abastecem por transferência da Central.']]};
REGRAS['Pedidos de compra']={aba:'Estoque · pedidos',itens:[['Fluxo','Rascunho → aprovação (acima de R$ 2.000; quem monta não aprova, exceto Administrador) → enviado → entrega parcial → recebido; encerrado (saldo cancelado) ou cancelado, sempre com motivo.'],['Em pedido','Enviado conta como "em pedido" e o ressuprimento não sugere de novo.'],['Recebimento','Nota fiscal obrigatória, quantidade, lote e validade por item; vira Entrada (custo médio) e conta a pagar no Financeiro (quem lança não paga).'],['Impressão','Pedido para imprimir ou PDF, com número para citar na nota.']]};
REGRAS['Inventário']={aba:'Estoque · inventário',itens:[['Tipos','Contagem de conferência ou implantação do saldo inicial; por unidade e escopo (todos, curva A, categoria).'],['Contagem','Folha impressa; às cegas esconde o saldo; digitação salva ao sair do campo.'],['Aplicar','Quem contou não aplica (exceto Administrador); sobras = ajuste (+) (ou saldo inicial), faltas = ajuste (−); não contados não mudam.'],['Cancelar','Com motivo; nenhum saldo muda.']]};
REGRAS['Relatórios do estoque']={aba:'Estoque · relatórios',itens:[['Relatórios','Posição do estoque, consumo por período e setor, consumo por procedimento ★, perdas, curva ABC, itens parados (90 dias) e compras por fornecedor com atrasos.'],['Saída','Imprimir, PDF e planilha CSV; respeitam a unidade do usuário.']]};
